"""Generate src/shell_tokens/digit_table.rs: ranges where Python's str.isdigit() is true."""
import sys
import unicodedata

ranges = []
start = None
for cp in range(0x110000):
    ok = chr(cp).isdigit()
    if ok and start is None:
        start = cp
    elif not ok and start is not None:
        ranges.append((start, cp - 1))
        start = None
out = [
    "// @generated by tools/gen_isdigit.py -- do not edit by hand.",
    f"//! Python {sys.version.split()[0]}, Unicode {unicodedata.unidata_version}: ranges where `str.isdigit()` is true.",
    "",
    "pub(super) const DIGIT_RANGES: &[(u32, u32)] = &[",
]
out += [f"    ({lo:#x}, {hi:#x})," for lo, hi in ranges]
out.append("];")
sys.stdout.write("\n".join(out) + "\n")
